/// Read a standalone element of `ink`, by its root. `None` if it is none of them.
// spec-audit: x:ink/2010/main:<context>
// spec-audit: x:powerpoint/2014/inkAction:<actions>
pub(crate) fn read_root(c: &mut SchemaReader<'_, '_>, el: &Elem) -> Res<Option<m::Root>> {
    if el.is(NS_INKML, "ink") {
        return Ok(Some(m::Root::Ink(Box::new(read_ink(c, el)?))));
    }
    if el.is(NS_INKML, "definitions") {
        return Ok(Some(m::Root::Definitions(Box::new(read_definitions(
            c, el,
        )?))));
    }
    if el.is(NS_INKML, "trace") {
        return Ok(Some(m::Root::Trace(Box::new(read_trace(c, el)?))));
    }
    if el.is(NS_INKML, "traceView") {
        return Ok(Some(m::Root::TraceView(Box::new(read_trace_view(c, el)?))));
    }
    if el.is(NS_MSINK, "context") {
        return Ok(Some(m::Root::MsinkContext(Box::new(read_msink_ctx_node(
            c, el,
        )?))));
    }
    if el.is(NS_IACT, "actions") {
        return Ok(Some(m::Root::ActionActions(Box::new(read_action_actions(
            c, el,
        )?))));
    }
    Ok(None)
}

/// Whether an element is one that [`read_root`] reads.
pub fn is_root(el: &Elem) -> bool {
    el.is(NS_INKML, "ink")
        || el.is(NS_INKML, "definitions")
        || el.is(NS_INKML, "trace")
        || el.is(NS_INKML, "traceView")
        || el.is(NS_MSINK, "context")
        || el.is(NS_IACT, "actions")
}
